<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\Holder\TrustedClientRegisteredAtAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TrustedClientRegisteredAtAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class TrustedClientRegisteredAtAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getRegisteredAt returns null on a freshly created holder.
     */
    public function testRegisteredAtNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientRegisteredAtAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isRegisteredAtAssigned());
        $this->assertNull($holder->getRegisteredAt());
    }
}
class ImplWithTrustedClientRegisteredAtAttributeHolderUnitTest
{
    use TrustedClientRegisteredAtAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedRegisteredAtRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultRegisteredAt();
    }
}
